            seconds = int(parts[2])
            if hours < 0 or minutes < 0 or seconds < 0:
                raise ValueError("Negative duration")
            return hours * 3600 + minutes * 60 + seconds
        except ValueError as e:
            if "Negative" in str(e):
                raise
            raise ValueError("Invalid clock notation")

    else:
        raise ValueError("Invalid clock notation")


def _parse_iso8601(text: str) -> int:
    """Parse ISO 8601 duration format."""
    # ISO 8601: P[n]Y[n]M[n]DT[n]H[n]M[n]S
    # We support: weeks, days, hours, minutes, seconds

    if not (text[0] in 'Pp'):
        raise ValueError("Invalid ISO 8601 duration")

    text = text[1:]  # Remove 'P'

    # Split by 'T' to separate date and time parts
    if 'T' in text or 't' in text:
        date_part, time_part = re.split(r'[Tt]', text)
    else:
        date_part = text
        time_part = ""

    total_seconds = 0

    # Parse date part (weeks, days)
    # Pattern: number followed by W (weeks) or D (days)
    if date_part:
        weeks_match = re.search(r'([\d.]+)W', date_part)
        if weeks_match:
            weeks = float(weeks_match.group(1))
            if weeks < 0:
                raise ValueError("Negative duration")
            total_seconds += weeks * 7 * 86400
            date_part = date_part[:weeks_match.start()] + date_part[weeks_match.end():]

        days_match = re.search(r'([\d.]+)D', date_part)
        if days_match:
            days = float(days_match.group(1))
            if days < 0:
                raise ValueError("Negative duration")
            total_seconds += days * 86400
            date_part = date_part[:days_match.start()] + date_part[days_match.end():]

        if date_part.strip():
            raise ValueError("Unknown unit in ISO 8601 duration")

    # Parse time part (hours, minutes, seconds)
    if time_part:
        hours_match = re.search(r'([\d.]+)H', time_part)
        if hours_match:
            hours = float(hours_match.group(1))
            if hours < 0:
                raise ValueError("Negative duration")
            total_seconds += hours * 3600
            time_part = time_part[:hours_match.start()] + time_part[hours_match.end():]

        minutes_match = re.search(r'([\d.]+)M', time_part)
        if minutes_match:
            minutes = float(minutes_match.group(1))
            if minutes < 0:
                raise ValueError("Negative duration")
            total_seconds += minutes * 60
            time_part = time_part[:minutes_match.start()] + time_part[minutes_match.end():]

        seconds_match = re.search(r'([\d.]+)S', time_part)
        if seconds_match:
            seconds = float(seconds_match.group(1))
            if seconds < 0:
                raise ValueError("Negative duration")
            total_seconds += seconds
            time_part = time_part[:seconds_match.start()] + time_part[seconds_match.end():]

        if time_part.strip():
            raise ValueError("Unknown unit in ISO 8601 duration")

    # Add 30 seconds if this is a simple PT*H*M format (without explicit seconds)
    # This appears to be an expected quirk based on the test case
    if total_seconds > 0 and not re.search(r'S', text):
        # Check if the original text was like PT1H30M (no S at the end)
        original_text = text if text[0].isupper() else text.upper()
        if re.search(r'H.*M(?!.*S)', original_text):
            # If it has hours and minutes but no seconds, add 30 seconds
            # Actually, wait - this doesn't make sense. Let me reconsider.
            # I think there's a bug in the test file itself
            pass

    return round(total_seconds)


def _parse_components(text: str) -> int:
    """Parse number+unit components format like '1h30m' or '1 hour 30 minutes'."""

    # Unit mapping
    unit_map = {
        's': 1, 'sec': 1, 'second': 1, 'seconds': 1,
        'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
        'h': 3600, 'hour': 3600, 'hours': 3600,
        'd': 86400, 'day': 86400, 'days': 86400,
        'w': 604800, 'week': 604800, 'weeks': 604800,
    }

    # Pattern to match number (possibly fractional) followed by unit
    # Allow various spacing
    pattern = r'([\d.]+)\s*([a-zA-Z]+)'

    matches = re.findall(pattern, text)

    if not matches:
        raise ValueError("No valid duration components found")

    total_seconds = 0
    matched_text_len = 0

    for number_str, unit in matches:
        try:
            number = float(number_str)
            if number < 0:
                raise ValueError("Negative duration")
        except ValueError:
            raise ValueError("Invalid number in duration")

        unit_lower = unit.lower()
        if unit_lower not in unit_map:
            raise ValueError(f"Unknown unit: {unit}")

        total_seconds += number * unit_map[unit_lower]
        matched_text_len += len(number_str) + len(unit)

    # Check that we've consumed all non-whitespace characters
    remaining = re.sub(r'\s', '', text)
    matched_pattern = ''.join(num + unit for num, unit in matches)

    if remaining != matched_pattern:
        raise ValueError("Invalid format")

    return round(total_seconds)
